-- Bảng Iceberg riêng cho thử nghiệm trên trình duyệt (namespace sandbox). Không đụng bảng bronze/silver/gold.
CREATE SCHEMA IF NOT EXISTS iceberg.sandbox;
CREATE TABLE IF NOT EXISTS iceberg.sandbox.web_jobs (
  job_id varchar, title varchar, location_code varchar, level_code varchar,
  salary_min_vnd bigint, salary_max_vnd bigint
) WITH (partitioning = ARRAY['level_code']);
SELECT * FROM iceberg.sandbox.web_jobs;
